namespace ghidra.macosx.analyzers;




using ghidra.app.services;
using ghidra.app.util.importer;
using ghidra.app.util.opinion;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.program.model.util;
using ghidra.util.exception;
using ghidra.util.task;

public class MachoConstructorDestructorAnalyzer : AbstractAnalyzer {
	private static readonly string NAME = "Mach-O Constructor/Destructor";
	private static readonly string DESCRIPTION =
		"Creates pointers to global constructors and destructors in a Mach-O file.";

	private static readonly string CONSTRUCTOR = "__constructor";
	private static readonly string DESTRUCTOR = "__destructor";

	public MachoConstructorDestructorAnalyzer() : base(NAME, DESCRIPTION, AnalyzerType.BYTE_ANALYZER)
    {
		setPriority(AnalysisPriority.FORMAT_ANALYSIS);
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {

		List<MemoryBlock> blocks = getBlocks(program);

		foreach (MemoryBlock block in blocks) {

			Address currentAddress = block.getStart();

			while (!monitor.isCancelled()) {
				if (currentAddress.compareTo(block.getEnd()) >= 0) {
					break;
				}
				try {
					Data data =
						program.getListing().createData(currentAddress, new PointerDataType());
					currentAddress = currentAddress.add(data.getLength());
				}
				catch (CodeUnitInsertionException e) {
					break;
				}
			}
		}

		return false;
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		return checkIfValid(program);
	}

	/* @Override */
	public bool getDefaultEnablement(Program program) {
		return checkIfValid(program);
	}

	private bool checkIfValid(Program program) {
		return !getBlocks(program).isEmpty();
	}

	private List<MemoryBlock> getBlocks(Program program) {
		List<MemoryBlock> list = new List<MemoryBlock>();
		if (program.getExecutableFormat().equals(MachoLoader.MACH_O_NAME)) {
			MemoryBlock[] blocks = program.getMemory().getBlocks();
			foreach (MemoryBlock block in blocks) {
				if (block.getName().equals(CONSTRUCTOR)) {
					list.add(block);
				}
				else if (block.getName().equals(DESTRUCTOR)) {
					list.add(block);
				}
			}
		}
		return list;
	}
}
